<?php $this->layout('default'); use Moves\Services\CmsAuth; use Moves\Services\PlatformDirectory; use Moves\Support\CmsView as V;
$d = PlatformDirectory::dashboard();
require dirname(__DIR__) . '/components/icons.php';
$kpiIcons = ['Usuários cadastrados' => 'users', 'Usuários ativos' => 'users', 'Novos cadastros em 30 dias' => 'users', 'Empresas cadastradas' => 'building', 'Assinaturas ativas' => 'repeat', 'Assinaturas pendentes' => 'clock', 'Assinaturas canceladas' => 'repeat', 'Planos contratados' => 'tag', 'Cobranças pendentes' => 'card', 'Receita recorrente mensal' => 'chart', 'Chamados abertos' => 'chat', 'Chamados pendentes' => 'clock', 'Em atendimento' => 'chat', 'Resolvidos' => 'shield', 'Primeira resposta (média)' => 'clock', 'Resolução (média)' => 'clock'];
$kpi = static fn (string $label, string $value): string => '<div class="cms-kpi"><i>' . $cmsIcon($kpiIcons[$label] ?? 'overview') . '</i><div><span>' . V::e($label) . '</span><strong>' . V::e($value) . '</strong></div></div>';
$section = static fn (string $title, string $link, string $href): string => '<div class="cms-section-head"><h2>' . V::e($title) . '</h2><a href="' . V::e($href) . '">' . V::e($link) . '</a></div>';
$shortcuts = array_filter([['/paginas/novo', 'Nova página', 'pages.manage'], ['/conteudos/novo', 'Novo conteúdo', 'content.manage'], ['/midia', 'Enviar mídia', 'media.manage'], ['/planos', 'Planos e preços', 'plans.view'], ['/chamados/fila', 'Fila de atendimento', 'tickets.view'], ['/configuracoes', 'Configurações', 'settings.manage']], static fn (array $item): bool => CmsAuth::can($admin, $item[2]));
$canCommercial = CmsAuth::can($admin, 'subscriptions.view'); $canPlatform = CmsAuth::can($admin, 'users.view'); $canTickets = CmsAuth::can($admin, 'tickets.view'); ?>
<p class="cms-lead">Olá, <?= V::e($admin['first_name']) ?>! Este é o resumo da plataforma hoje.</p>
<?php if ($canPlatform): ?><?= $section('Plataforma', 'Ver usuários', '/usuarios') ?><div class="cms-kpis"><?= $kpi('Usuários cadastrados', (string) $d['users_total']) . $kpi('Usuários ativos', (string) $d['users_active']) . $kpi('Novos cadastros em 30 dias', (string) $d['users_new_30']) . $kpi('Empresas cadastradas', (string) $d['companies_total']) ?></div><?php endif; ?>
<?php if ($canCommercial): ?><?= $section('Comercial', 'Ver assinaturas', '/assinaturas') ?><div class="cms-kpis"><?= $kpi('Assinaturas ativas', (string) ($d['subs']['active'] ?? 0)) . $kpi('Assinaturas pendentes', (string) ($d['subs']['pending'] ?? 0)) . $kpi('Assinaturas canceladas', (string) ($d['subs']['canceled'] ?? 0)) . $kpi('Planos contratados', (string) $d['plans_contracted']) . $kpi('Cobranças pendentes', (string) $d['charges_pending']) . $kpi('Receita recorrente mensal', V::money($d['mrr'])) ?></div><?php endif; ?>
<?php if ($canTickets): ?><?= $section('Atendimento', 'Abrir fila', '/chamados/fila') ?><div class="cms-kpis"><?= $kpi('Chamados abertos', (string) ($d['tickets']['open'] ?? 0)) . $kpi('Chamados pendentes', (string) $d['tickets_pending']) . $kpi('Em atendimento', (string) ($d['tickets']['in_progress'] ?? 0)) . $kpi('Resolvidos', (string) (($d['tickets']['resolved'] ?? 0) + ($d['tickets']['closed'] ?? 0))) . $kpi('Primeira resposta (média)', V::minutes($d['first_response_avg'])) . $kpi('Resolução (média)', V::minutes($d['resolution_avg'])) ?></div><?php endif; ?>
<?php if ($shortcuts !== []): ?><section class="cms-card"><h2>Ações rápidas</h2><div class="cms-actions"><?php foreach ($shortcuts as [$href, $label]): ?><a class="cms-btn" href="<?= V::e($href) ?>"><?= V::e($label) ?></a><?php endforeach; ?></div></section><?php endif; ?>
